"""Authored situations, information branches and commitments; no generated dialogue."""
PEOPLE={'alex':('Alex Rao','Delivery manager'),'daniel':('Daniel Mercer','Project manager'),'priya':('Priya Shah','Finance & staffing'),'maya':('Maya Chen','Implementation specialist'),'jordan':('Jordan Ellis','Implementer'),'sam':('Sam Patel','Trainee'),'elena':('Elena Ortiz','Client sponsor'),'rosa':('Rosa Alvarez','Warehouse lead'),'nikhil':('Nikhil Desai','Senior engineer'),'marcus':('Marcus Reed','Sales lead'),'mentor':('Your live mentor','Human advisor')}
STAFF={'maya':dict(cost=60000,pace=.85,support=0,skill='Complex implementation, migration dependencies and independent technical execution',limit='Cannot decide client business policy or absorb unlimited scope'), 'jordan':dict(cost=30000,pace=1,support=10000,skill='Implementation against clear requirements and agreed technical standards',limit='Needs direction on ambiguity and early technical review'),'sam':dict(cost=0,pace=1.2,support=15000,skill='Strong academic preparation and careful execution of bounded tasks',limit='No delivery experience; needs teaching, senior sign-off and specialist help')}
def opt(text,key,cost=0,days=0,visible=(0,0,0),skills=(0,0,0)):
 return dict(text=text,key=key,cost=cost,days=days,visible=dict(zip(('client','manager','board'),visible)),skills=dict(zip(('leadership','people','decision'),skills)))
def question(text,who,answer,fact,skills=(0,0,1),days=0,visible=(0,0,0)):
 return dict(text=text,who=who,answer=answer,fact=fact,skills=dict(zip(('leadership','people','decision'),skills)),days=days,visible=dict(zip(('client','manager','board'),visible)))
def stage(s):
 n=s['step'];w=s.get('staff') or 'maya';name=PEOPLE[w][0].split()[0];f=s['flags'];hard=f.get('pressure')=='hard';event=f.get('event','stable');removed=f.get('absent',False)
 q=lambda *a,**k:question(*a,**k)
 options=[];questions=[];thread='project';who=w;title='';lines=[]
 if n==1:
  title='Choose implementation responsibility';who='priya';thread='priya';lines=['I have three screened candidates. Each brings a different kind of capacity. Their files and packages are in Candidates.','What do you need this hire to own? You can ask for details or commit when you have enough information.']
  questions=[q('What would each person take off my plate?','priya','Maya can own complex implementation. Jordan needs clear priorities and review. Sam needs structured tasks, teaching and senior approval. You retain business commitments in every case.','roles'),q('What does the project still need after we hire?','priya','The base team and platform work commit $180,000. Hiring does not pay for verification, user training or new scope. Our base authorization is $300,000; the savings target is $20,000.','budget'),q('What matters most to you, Daniel?','daniel','Usable, verified delivery first. Consult the client on business policy; bring funding and scope changes to me before committing them.','authority',(1,0,1)),q('What happens if Sam needs work beyond his experience?','nikhil','Senior review uses real capacity. I can support bounded tasks; if we cannot cover specialist work internally, it needs an approved external package.','support',(1,1,1))]
  options=[opt('Bring Maya in. I want independent implementation while I manage commitments.','maya',60000,1,(0,2,0),(1,0,1)),opt('Bring Jordan in. I will plan clear direction and technical review.','jordan',30000,1,(0,1,0),(1,1,1)),opt('Give Sam the placement. I will arrange teaching and senior sign-off.','sam',0,1,(0,0,0),(1,1,1))]
 elif n==2:
  title='Available stock: one business rule';lines=[f'{name}: sales wants the dashboard to show physical stock; operations wants only stock available to promise. I can implement a rule, but you need to decide which business behavior to propose.','Example: 100 units present, 30 reserved, 10 quarantined. We need client approval before this becomes the acceptance rule.']
  questions=[q('Marcus, why does sales need the physical total?','marcus','Sales needs visibility of all 100 units when discussing delivery dates. That does not mean permission to promise units already reserved or quarantined.','sales'),q('Rosa, what can we promise to a new order?','rosa','Only 60 units. Reservations belong to existing commitments; quarantine needs an authorized release. A later date can be discussed without allocating unavailable units.','stock'),q('Elena, who approves the rule and what must it achieve?','elena','I approve the cross-department rule. Display the breakdown, but prevent new orders consuming reserved or quarantined stock. Bring me an acceptance example.','policy'),q('Daniel, can we decide this ourselves?','daniel','You recommend the rule; Elena approves client business policy. Maya explains implementation. Keep display visibility separate from order authorization.','authority',(1,0,1)),q(f'{name}, can we show both totals? ',w,'Yes. We can display physical, reserved, quarantined and available quantities separately, with the order check driven by released, unreserved units.','technical')]
  options=[opt('Propose the stock breakdown and use released, unreserved stock for new orders.','rule',10000,2,(2,2,1),(1,0,2)),opt('Use physical stock for order promises. We can resolve allocations later.','physical',0,0,(-2,-2,0),(0,0,-2)),opt('Subtract reservations but include quarantined stock.','quarantine',0,0,(-1,-1,0),(0,0,-1)),opt(f'Ask {name} to choose the business policy for us.','delegate_policy',0,0,(0,-1,0),(-1,0,-1))]
 elif n==3:
  title='Migration evidence';who='nikhil';lines=['Warehouse three has duplicate records. A polished screen cannot prove that migrated quantities are correct.','How much evidence do you want before the client relies on these numbers?']
  questions=[q('What does the duplicate risk actually affect?','nikhil','It can inflate stock and create promises we cannot fulfill. Full audit checks all sites; a sample supports a bounded pilot, not an unconditional rollout.','data'),q(f'What review support does {name} need here?',w,{'maya':'I can own the migration investigation with Nikhil reviewing acceptance evidence.','jordan':'I need an agreed mapping standard and review before repeating it across sites.','sam':'Show me one mapping example, then review my corrected sample. Nikhil must sign off production work.'}[w],'review',(1,1,1))]
  options=[opt('Audit all three warehouses and review the mapping before migration.','audit',10000+STAFF[w]['support'],4,(1,2,1),(1,1,2)),opt('Verify a sample and label the release as a pilot until coverage is extended.','sample',4000,2,(0,1,0),(0,0,1)),opt('Use the supplied records. We cannot spend more time checking.','skip_data',0,0,(-2,-2,0),(0,0,-2))]
 elif n==4:
  title='Acceptance priorities';who='elena';lines=['Every department has sent a wish list. Can I tell them everything will be ready in sixteen weeks?']
  questions=[q('Which items are essential for acceptance?','elena','Reliable inventory and order flow are essential. Additional wishes need separate scope review; I can approve ranked priorities.','scope'),q('What happens if I promise the whole list?','daniel','You would expand the commitment without an implementation or funding assessment. Clarifying priorities takes coordination now but limits rework later.','tradeoff',(1,0,1))]
  options=[opt('Agree ranked acceptance priorities and record additional requests separately.','priorities',0,2,(1,2,1),(1,0,2)),opt('Promise every request by the existing deadline.','promise_all',0,0,(2,-2,-1),(-1,0,-2))]
 elif n==5:
  title='Prototype review';lines=[f'{name}: the working core is ready to demonstrate. It is not yet a certified production release.'];who=w
  questions=[q('What can we honestly demonstrate today?',w,'The implemented core against the current requirements. Migration, regression coverage and user readiness still need evidence.','demo'),q('Elena, how will you use this demonstration?','elena','To report progress. Tell me which parts are confirmed so I do not present a prototype as a release commitment.','reliance')]
  options=[opt('Show the working core and the assumptions still needing proof.','honest',0,3,(2,2,1),(1,0,2)),opt('Describe the system as nearly finished.','overstate',0,1,(1,-2,0),(-1,0,-2))]
  if w=='sam':lines=['The demonstration build is ready. I’ve completed the order example we discussed.']
 elif n==6:
  title='A changed operating environment';who='daniel';lines={'stable':['The client has kept the scope bounded. There is no new constraint at this checkpoint. Reconcile what remains before the next commitment.'],'cut':['The board reduced authorization by $30,000 because of competing commitments. Existing costs remain payable. I will support a documented appeal if the cut makes the agreed delivery unviable.'],'removal':[f'{name} has been reassigned to a critical incident. Their package is already committed; we cannot refund it. We need an accountable handover and replacement plan.'],'scope':['Elena has added daily exception alerts across all warehouses without extending the deadline. This is real additional scope. Assess it before promising the work.']}[event]
  questions=[q('What can we negotiate before making another promise?','daniel','We can review scope, date and justified authorization with the decision owners. A documented request is stronger than promising first and asking afterward.','negotiation',(1,0,1)),q('What commitments remain payable?','priya','The commitments shown in Budget remain incurred. A budget cut or staff reassignment does not erase them. Future work must stay inside approved funding.','commitments'),q('Elena, can we clarify what is necessary now?','elena','Show me the operational impact and a proposed sequence. I may accept a bounded phase, but I will not accept an unexplained deletion of agreed work.','sequence')]
  options=[opt('Review the evidence and reconcile commitments before proposing a response.','diagnose',0,2,(0,2,1),(1,0,2)),opt('Promise to make it work before checking capacity.','blind',0,0,(1,-2,-1),(-1,0,-2)),opt('Accuse the stakeholder of undermining the project.','accuse',0,0,(-3,-3,-2),(-1,-2,-1))]
 elif n==7:
  title='Recovery ownership';who='daniel';lines=['We have the updated conditions. What response are you authorizing?']
  questions=[q('Which work is optional and which protects acceptance?','nikhil','Presentation extras can be removed. Stock-rule correctness, migration verification, user readiness and accepted scope cannot simply disappear.','essentials'),q('What does a proper handover include?','nikhil','Requirements, decisions, implementation context and review ownership. Reassignment without those creates avoidable rework.','handover',(1,1,1))]
  if event=='scope':options=[opt('Assess and implement the alerts with funded verification.','recovery',10000 if w=='maya' else 15000 if w=='jordan' else 20000,5,(1,2,0),(1,0,2)),opt('Push the alerts into the build without extra review.','rush_scope',5000,2,(1,-2,-1),(-1,0,-2)),opt('Negotiate a phased alert plan with funded completion.','phase_scope',5000,3,(-1,1,0),(1,0,1))]
  elif event=='removal':options=[opt('Fund a documented handover and senior-team reassignment.','recovery',6000,5,(0,2,0),(1,1,2)),opt('Fund a qualified replacement and reconfirm responsibilities.','recovery_external',18000,4,(0,1,-1),(1,0,1)),opt('Divide the tasks without a transition plan.','fragment',0,1,(0,-2,0),(-1,-1,-2))]
  else:options=[opt('Protect the core and review gates; remove optional extras.','recovery',0,1,(0,2,1),(1,0,2)),opt('Cut review capacity first to reduce the burden.','cut_review',0,0,(0,-2,1),(-1,-1,-2)),opt('Reconfirm a smaller accepted scope before committing further work.','phase_scope',4000,2,(-1,1,0),(1,0,1))]
 elif n==8:
  title='Capacity and weekend recovery';thread=w;who=w;lines=['The schedule is under pressure. We have a possible weekend access window, but people have commitments and the work needs a stopping point.' if f.get('rework') or event!='stable' else 'Before the next release tasks, let’s review ownership and workload. We can protect the schedule without assuming unlimited capacity.']
  questions=[q('What is the actual availability and a safe stopping point?',w,'Ask each person. If needed, use one bounded validation window, documented cover and time back. One weekend cannot substitute for a feasible plan.','capacity',(1,1,1)),q('Daniel, how should we handle the deadline pressure?','daniel','Challenge the constraint with evidence. I support clear standards and escalation; I do not support threats or unlimited weekend commitments.','pressure',(1,1,1))]
  options=[opt('Check availability, set a bounded plan and honor time back.','support_people',0,1,(0,2,0),(2,2,1)),opt('Demand everyone work until the problem is solved.','shame',0,0,(0,-2,0),(-2,-2,-1)),opt('Avoid discussing standards or support; tell everyone it is fine.','avoid',0,0,(0,-1,0),(-1,-1,-1))]
 elif n==9:
  title='Verification coverage';who='nikhil';lines=['What coverage should support the release? Earlier audited data helps, but implementation still needs verification.']
  questions=[q('Can we reuse evidence for a focused cross-site check?','nikhil','Only if requirements and data are verified, mapping has review ownership, and the current build is correct. Otherwise the focused route supports only a pilot.','reuse'),q('What does the client need to accept all sites?','elena','Evidence for the actual scope at all three sites. A pilot result cannot be relabeled as complete coverage.','coverage')]
  options=[opt('Fund full regression and migration checks across all three sites.','full_tests',12000,6,(1,2,0),(1,0,2)),opt('Test a bounded pilot and retain the coverage limit.','pilot_tests',6000,3,(0,1,0),(0,0,1)),opt('Skip additional testing and use the base minimum.','minimum_tests',0,0,(-1,-2,0),(-1,0,-2)),opt('Reuse verified data with senior-led focused cross-site checks.','lean_tests',2000,4,(1,2,1),(1,0,2))]
 elif n==10:
  title='Readiness finding';who='nikhil';risk=f.get('defect') or not f.get('tests');lines=['We have an unresolved readiness gap. Repair, reduced scope or additional evidence needs an explicit decision.' if risk else 'No material defect remains. We can run a rollback exercise or preserve the funds against later work.']
  questions=[q('What is the consequence of this finding?','nikhil','An unverified or incorrect core cannot be made safe by a positive report. Repair must be verified; optional work can be deferred only with sponsor approval.','finding'),q('Can Elena agree a deferral?','elena','Optional work may be deferred explicitly. Core stock correctness and the remaining agreed delivery still need a funded completion plan.','deferral')]
  options=[opt('Repair the finding and retest.' if risk else 'Run the rollback and resilience exercise.','repair',8000 if risk else 4000,5 if risk else 2,(1,2,0),(1,0,2)),opt('Negotiate an optional-feature deferral.' if risk else 'Retain the reserve; existing evidence is sufficient.','defer' if risk else 'retain',0,1,(-1,1,0) if risk else (0,1,1),(1,0,1)),opt('Conceal the finding.' if risk else 'Skip the extra exercise without reviewing the evidence.','conceal' if risk else 'skip_resilience',0,0,(-2,-2,0),(-1,0,-2))]
 elif n==11:
  title='User readiness';who='rosa';lines=['A technically working system still needs people able to use it. How are we preparing the warehouses?']
  questions=[q('What would an internal rehearsal require?','rosa','Verified workflows, named champions and reviewed materials. When those exist, we can reuse them. Otherwise a brief handover is not equivalent to three-site readiness.','champions',(1,1,1)),q('How does fatigue affect the handover?','rosa','Unbounded overtime makes practice and problem reporting worse. We need coverage and a realistic rehearsal schedule.','fatigue',(1,1,1))]
  options=[opt('Train and rehearse the workflow across all three warehouses.','full_training',10000,5,(2,2,0),(1,1,2)),opt('Prepare one warehouse with a funded completion sequence.','pilot_training',4000,3,(0,1,0),(1,1,1)),opt('Use standard handover only.','minimum_training',0,1,(-1,-1,0),(-1,0,-1)),opt('Use internal champions and reviewed materials for a cross-site rehearsal.','lean_training',2500,4,(1,2,1),(1,1,2))]
 elif n==12:
  title='Report the real position';who='daniel';lines=['The readiness report is the basis for the next committee decision. What are you putting on the record?']
  questions=[q('What evidence should accompany the report?','daniel','Accepted scope, verified results, spending, dates, user readiness and explicit limits. Distinguish delivered work from a future commitment.','report',(1,0,1))]
  options=[opt('Present results, costs, dates and the limits that remain.','transparent',0,1,(1,2,1),(2,0,2)),opt('Show only the strongest parts of the project.','selective',0,0,(0,-1,0),(-1,0,-1)),opt('Declare ready despite unresolved gates.','false_ready',0,0,(-2,-3,0),(-2,0,-2))]
 elif n==13:
  title='Leadership and a difficult client';who='daniel';lines={'supportive':['I will support an honest delivery plan. Show what is ready and what needs a decision.'],'critical':['I expected this to be easier and I am pressing for a full launch. You still need to challenge me if the record does not support it.'],'hard':['Elena now requires a validated legacy interface and additional acceptance coverage. Her supplied specification was incomplete. I will support justified funding, but we cannot certify unvalidated work in forty-eight hours.']}[f.get('pressure','supportive')]
  questions=[q('What exactly is Elena requiring and who approves it?','elena','The alerts, legacy interface and expanded acceptance checks remain required. I can agree a verified sequence; I will not accept an unexplained deletion.' if hard else 'The approved inventory and order scope remains the baseline. New requests need explicit review; I can approve acceptance boundaries and any agreed sequence.','hard_scope'),q('Daniel, can we negotiate the impossible deadline?','daniel','Bring the validated mismatch, required checks and feasible sequence. I can defend a supported boundary, but leadership backing does not certify unfinished work.','challenge',(2,0,2)),q('What specialist work is still needed?','nikhil','The legacy interface requires specialist integration and expanded validation. Use staged, approved funding and preserve the checks.','specialist')]
  options=[opt('Present evidence and negotiate a feasible, verified delivery sequence.','evidence',0,2,(0,2,1),(2,1,2)),opt('Accept the forty-eight-hour demand without changing conditions.','forced',0,0,(1,-2,0),(-2,0,-2)),opt('Attack the client or director in the steering discussion.','attack',0,0,(-3,-3,-2),(-2,-2,-2))]
 elif n==14:
  title='Accepted completion plan';who='elena';lines=['What delivery are you asking me to accept? Additional authorization does not substitute for the remaining work.']
  questions=[q('Can we review every requirement and remaining gate?','elena','Review stock correctness, data, tested workflows, user readiness and additional agreed scope. Choose full release only when the evidence supports it.','acceptance'),q('What would a funded completion plan add?','nikhil','It funds remaining checks and training with an accepted revised sequence. We must actually execute those tasks before recording completion.','completion')]
  options=[opt('Confirm the full release against the acceptance evidence.','full_accept',0,1,(1,1,0),(1,0,1)),opt('Agree a phased release and fund the remaining validation and training.','phase_accept',10000,8,(0,1,0),(1,1,1)),opt('Agree a revised date and a reviewed recovery package.','delay_accept',10000,10,(-1,1,0),(1,0,1))]
 else:
  title='Authorize and account for delivery';who='daniel';lines=['The release decision must match the agreed plan, actual verification and funding. What are you authorizing?']
  questions=[q('Does the evidence support the plan we agreed?','nikhil','Use the Scope record. Failed gates require a completed recovery; high stakeholder scores cannot turn incomplete work into accepted delivery.','final_check')]
  options=[opt('Authorize the full rollout against the verified acceptance record.','launch',0,2,(1,1,0),(1,0,1)),opt('Execute the agreed phased completion before final acceptance.','finish_phase',0,5,(0,1,0),(1,1,1)),opt('Hold release and execute the agreed recovery before acceptance.','finish_delay',0,7,(-1,1,0),(1,0,1))]
 if n==14:
  options.append(opt('Document that the required work cannot be funded and request an orderly stop.','stop_accept',0,1,(-1,1,0),(1,1,1)))
 if n==15:
  options.append(opt('Close the project honestly without certifying unmet requirements.','close',0,1,(-1,1,0),(1,1,1)))
 # Different hires change duration, review needs and language, not the business owner's authority.
 if n not in (1,6,12,13,14,15):
  for o in options:o['days']=round(o['days']*STAFF[w]['pace'])
 if removed and n>6:
  if who==w:who='nikhil'
  if thread==w:thread='nikhil'
  for item in questions:
   if item['who']==w:item['who']='nikhil'
 return dict(title=title,thread=thread,who=who,lines=lines,questions=questions,options=options)
